-- Schema awal Supabase. Audit RLS dan uji semua role sebelum membuka aplikasi publik.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Anggota Zerava',job_title text not null default 'Anggota',avatar_url text,bio text,created_at timestamptz not null default now());
create table if not exists public.servers(id uuid primary key default gen_random_uuid(),name text not null,description text,owner_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.server_members(server_id uuid references public.servers(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','admin','moderator','member')),joined_at timestamptz not null default now(),primary key(server_id,user_id));
create table if not exists public.channels(id uuid primary key default gen_random_uuid(),server_id uuid not null references public.servers(id) on delete cascade,name text not null,channel_type text not null default 'text',created_at timestamptz not null default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,body text not null,media_url text,created_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,server_id uuid references public.servers(id) on delete set null,title text not null,synopsis text,project_type text default 'Film Pendek',status text not null default 'Pengembangan',target_date date,created_at timestamptz not null default now());
create table if not exists public.academy_materials(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,title text not null,category text not null,body text,video_url text,cover_url text,created_at timestamptz not null default now());
create table if not exists public.bookmarks(user_id uuid not null references auth.users(id) on delete cascade,material_id uuid not null references public.academy_materials(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,material_id));
alter table public.profiles enable row level security; alter table public.servers enable row level security; alter table public.server_members enable row level security; alter table public.channels enable row level security; alter table public.posts enable row level security; alter table public.projects enable row level security; alter table public.academy_materials enable row level security; alter table public.bookmarks enable row level security;
create policy "profiles public read" on public.profiles for select using(true);
create policy "profile own insert" on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy "profile own update" on public.profiles for update to authenticated using(auth.uid()=id);
create policy "servers public read" on public.servers for select using(true);
create policy "users create own servers" on public.servers for insert to authenticated with check(auth.uid()=owner_id);
create policy "server owner update" on public.servers for update to authenticated using(auth.uid()=owner_id);
create policy "server owner delete" on public.servers for delete to authenticated using(auth.uid()=owner_id);
create policy "memberships read" on public.server_members for select using(true);
create policy "join self" on public.server_members for insert to authenticated with check(auth.uid()=user_id);
create policy "leave self" on public.server_members for delete to authenticated using(auth.uid()=user_id);
create policy "channels read" on public.channels for select using(true);
create policy "server owner creates channels" on public.channels for insert to authenticated with check(exists(select 1 from public.servers s where s.id=server_id and s.owner_id=auth.uid()));
create policy "posts read" on public.posts for select using(true);
create policy "create own posts" on public.posts for insert to authenticated with check(auth.uid()=author_id);
create policy "edit own posts" on public.posts for update to authenticated using(auth.uid()=author_id);
create policy "delete own posts" on public.posts for delete to authenticated using(auth.uid()=author_id);
create policy "projects read" on public.projects for select using(true);
create policy "create own projects" on public.projects for insert to authenticated with check(auth.uid()=owner_id);
create policy "update own projects" on public.projects for update to authenticated using(auth.uid()=owner_id);
create policy "delete own projects" on public.projects for delete to authenticated using(auth.uid()=owner_id);
create policy "academy read" on public.academy_materials for select using(true);
create policy "publish own academy" on public.academy_materials for insert to authenticated with check(auth.uid()=author_id);
create policy "edit own academy" on public.academy_materials for update to authenticated using(auth.uid()=author_id);
create policy "delete own academy" on public.academy_materials for delete to authenticated using(auth.uid()=author_id);
create policy "own bookmarks read" on public.bookmarks for select to authenticated using(auth.uid()=user_id);
create policy "own bookmarks add" on public.bookmarks for insert to authenticated with check(auth.uid()=user_id);
create policy "own bookmarks delete" on public.bookmarks for delete to authenticated using(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
